# Content for the history-of-theory guide, chapters 0-15.
# Paraphrased from Christensen (ed.), The Cambridge History of Western Music Theory (CUP 2002, 3rd printing 2006).
# Page refs are to the printed book. "R" = a precept stated by a historical theorist (who and where is given);
# "G" = a guideline, interpretation, or the chapter author's own conclusion.

def T(name, dates, works, idea):
    return {'name': name, 'dates': dates, 'works': works, 'idea': idea}
def W(title, year):
    return {'title': title, 'year': year}
def Q(q, opts, ans, why):
    return {'q': q, 'options': opts, 'answer': ans, 'why': why}

CH = []
def chapter(**k):
    k.setdefault('rules', []); k.setdefault('guidelines', []); k.setdefault('tools', []); k.setdefault('links', [])
    CH.append(k)

chapter(id='intro', num=0, part='front', section=None, title='Introduction: theory that resists its own history', author='Thomas Christensen', pages='1–26',
  summary='Christensen asks how one can write a history of a subject whose very content keeps changing. Counterpoint and figured bass were once outside "theory", while the old mathematical science of music (musica theorica) now looks marginal. He proposes a flexible network of meanings instead of a fixed definition, and organizes the book by three broad traditions: speculative, regulative and descriptive (analytic).',
  points=['Three texts from about 1618 show how wide the field was: Campion\'s practical rule for four-part writing, Descartes\'s rational <i>Compendium musicae</i>, and Fludd\'s cosmological <i>Utriusque cosmi</i>.',
          'The Greek root <i>theoria</i> means contemplation. Aristotle set it against practical knowledge; the Middle Ages turned this into <i>musica theorica</i> (a quadrivial science of number) versus <i>musica practica</i> (singing, notation, composition).',
          'From the 19th-century conservatories onward, theory split into competing disciplines (harmony, counterpoint, form, acoustics, psychology). In the late 20th century it became an academic field of its own.',
          'Plan of the book: Part I disciplining theory; Part II speculative traditions; Part III regulative traditions (tonal space, composition, time, tonality); Part IV descriptive traditions (analysis, psychology).',
          'Theory is reflexive and historical: it claims timeless truths, yet each version is bound to its own practice and culture.'],
  terms=[('musica theorica', 'Music as a speculative science of number and proportion, one of the four quadrivial arts.'),
         ('musica practica', 'Practical music: singing, notation, counterpoint, composition and performance.'),
         ('speculative / regulative / analytic', 'The three traditions (after Dahlhaus) used to organize the volume: knowledge of music\'s nature, rules for making music, and description of finished works.')],
  theorists=[T('Carl Dahlhaus', '1928–89', [], 'Warned that music theory "resists its own history"; proposed the speculative, regulative and analytic traditions.'),
             T('Thomas Campion', '1567–1620', [W('A New Way of Making Fowre Parts in Counter-point', 'c. 1618')], 'A practical rule-of-thumb method for four-part writing.'),
             T('René Descartes', '1596–1650', [W('Compendium musicae', '1618; pub. 1650')], 'A rational, mechanistic account of consonance and the passions.'),
             T('Robert Fludd', '1574–1637', [W('Utriusque cosmi … historia', '1617–21')], 'A cosmic, neo-Platonic harmony linking universe and human being.')],
  quiz=[Q('Which pair of terms frames the medieval split that the book traces?', ['harmony / counterpoint', 'musica theorica / musica practica', 'tonal / atonal', 'melody / rhythm'], 1, 'Speculative musica theorica (a quadrivial science) versus practical musica practica.'),
        Q('What three broad traditions organize the volume?', ['Ancient, medieval, modern', 'Speculative, regulative, descriptive (analytic)', 'Pitch, rhythm, form', 'French, Italian, German'], 1, 'Christensen follows Dahlhaus\'s three-way division.')])

chapter(id='mapping', num=1, part='I', section=None, title='Mapping the terrain', author='Leslie Blasius', pages='27–45',
  summary='Every musical culture draws a "map" of what its theory covers. Blasius follows these maps from Aristides Quintilianus\' complete architecture, through scholastic and Renaissance schemes, to the Enlightenment taxonomies and Guido Adler\'s 1885 plan for musicology.',
  points=['Aristides Quintilianus\' <i>On Music</i> (early 4th c. CE) is the first complete surviving architecture: a theoretical side (physics; technical study of harmonics, rhythmics and metrics) and a practical side (composition and performance).',
          'Marchetto of Padua\'s <i>Lucidarium</i> (1317–18) sorts music by purely sounding (phenomenal) criteria, typical of 14th-century scholasticism.',
          'In the 16th century, mapping becomes synthetic: treatises gather everything into one harmonized whole.',
          'Mersenne\'s <i>Harmonie universelle</i> (1636–37) is organized by physics, mechanics and instruments. Kircher\'s <i>Musurgia universalis</i> (1650) is organized by similitudes, magic and correspondence. Their contrast marks the 17th-century epistemic shift.',
          'Forkel\'s plan (late 18th c.) divides music into a grammar and a rhetoric. Adler\'s 1885 plan divides musicology into a historical and a systematic field; he printed it beside Aristides\' table.'],
  terms=[('schema', 'A map that divides a body of knowledge into idealized categories.'),
         ('historical vs systematic musicology', 'Adler\'s division: history (notation, genres, laws as they evolved, instruments) versus systematics (laws, aesthetics, pedagogy, comparative musicology).')],
  theorists=[T('Aristides Quintilianus', 'late 3rd–4th c. CE', [W('On Music', 'c. 300')], 'First complete map of music theory.'),
             T('Marchetto of Padua', 'fl. 1305–19', [W('Lucidarium', '1317–18')], 'Scholastic classification of music by sound.'),
             T('Marin Mersenne', '1588–1648', [W('Harmonie universelle', '1636–37')], 'Mechanistic, physical organization of music.'),
             T('Athanasius Kircher', '1601/2–80', [W('Musurgia universalis', '1650')], 'Universal music of correspondences and combinatorics.'),
             T('Johann Nikolaus Forkel', '1749–1818', [W('Allgemeine Geschichte der Musik', '1788–1801')], 'Music as a language with grammar and rhetoric.'),
             T('Guido Adler', '1855–1941', [W('"Umfang, Methode und Ziel der Musikwissenschaft"', '1885')], 'Map of musicology: historical and systematic fields.')],
  quiz=[Q('Who drew the first complete surviving architecture of music theory?', ['Boethius', 'Aristides Quintilianus', 'Guido', 'Zarlino'], 1, 'On Music, early 4th century CE.'),
        Q('Mersenne\'s Harmonie universelle is organized mainly by…', ['magic and similitudes', 'physics, mechanics and instruments', 'the eight modes', 'rhetorical figures'], 1, 'Kircher is the one organized by similitudes and correspondences.')])

chapter(id='practica', num=2, part='I', section=None, title='Musica practica: music theory as pedagogy', author='Robert W. Wason', pages='46–77',
  summary='Wason tells how practical teaching (singing, counterpoint, thoroughbass, harmony) slowly absorbed the old speculative theory. The story runs from medieval schools and universities to Renaissance composition manuals, thoroughbass, the conservatories of Paris, Vienna and Berlin, and the North American academy.',
  points=['Medieval teaching was practical and Carolingian in spirit (chant, notation, the monochord). The universities taught Boethian musica as a quadrivial art.',
          'Renaissance composition pedagogy grew with humanism and with more ambitious genres (Tinctoris; Zarlino\'s <i>Le istitutioni harmoniche</i>, 1558).',
          'Heinichen\'s thoroughbass treatise (1728) is a complete composition course that teaches styles through the figured bass.',
          'Koch\'s <i>Versuch</i> (1782–93) builds an empirical vocabulary of phrase and period, borrowed from grammar and rhetoric.',
          'Around 1800 the national traditions blend: French fundamental bass, Italian species counterpoint (and partimento), German thoroughbass.',
          'Conservatory texts follow: Catel in Paris (1802); Sechter in Vienna (<i>Grundsätze</i>, 1853–54; he gave Schubert a counterpoint lesson); Marx in Berlin.',
          'In the 20th century came Louis & Thuille (1906), Schoenberg\'s <i>Harmonielehre</i> (1911), Schenker\'s posthumous American influence, Boulanger, and Hindemith at Yale. Babbitt\'s Princeton program and <i>Perspectives of New Music</i> made the composer-theorist a model; Wason regrets theory\'s loss of contact with living composition.'],
  terms=[('thoroughbass (Generalbass)', 'Improvised accompaniment from a bass line with figures; in Germany the core of composition teaching.'),
         ('fundamental bass', 'Rameau\'s bass of chord roots, the French analytical tradition.'),
         ('Kompositionslehre', 'A comprehensive "doctrine of composition" (Marx), including forms.')],
  theorists=[T('Johann David Heinichen', '1683–1729', [W('Der General-Bass in der Composition', '1728')], 'Thoroughbass as a full composition course.'),
             T('Heinrich Christoph Koch', '1749–1816', [W('Versuch einer Anleitung zur Composition', '1782–93')], 'Phrase grammar and punctuation of melody.'),
             T('Charles-Simon Catel', '1773–1830', [W('Traité d\'harmonie', '1802')], 'Paris Conservatoire\'s pragmatic harmony text.'),
             T('Simon Sechter', '1788–1867', [W('Die Grundsätze der musikalischen Komposition', '1853–54')], 'Viennese fundamental-bass theory; taught Bruckner.'),
             T('Adolf Bernhard Marx', '1795–1866', [W('Die Lehre von der musikalischen Komposition', '1837–47'), W('Allgemeine Musiklehre', '1839')], 'Progressive, Pestalozzian composition pedagogy in Berlin.'),
             T('Arnold Schoenberg', '1874–1951', [W('Harmonielehre', '1911')], 'Harmony taught from the composer\'s craft.'),
             T('Milton Babbitt', '1916–2011', [], 'Princeton composer-theorist model; co-founded Perspectives of New Music.')],
  quiz=[Q('Which three national traditions blended around 1800?', ['French fundamental bass, Italian counterpoint, German thoroughbass', 'English glee, French opera, Italian madrigal', 'Greek, Latin, Byzantine', 'Schenker, Riemann, Schoenberg'], 0, 'Wason\'s summary of practical theory c. 1800.'),
        Q('Whose 1728 thoroughbass treatise works as a complete course in composition?', ['Rameau', 'Heinichen', 'Fux', 'Mattheson'], 1, 'Heinichen, Der General-Bass in der Composition.')],
  links=['partimento', 'harmony'])

chapter(id='epistemology', num=3, part='I', section=None, title='Epistemologies of music theory', author='Nicholas Cook', pages='78–108',
  summary='What kind of knowledge is music theory? Cook follows how its grounding moved over time. It began in theology and cosmology, passed to natural science (Rameau\'s claims about nature), and ended in psychology and phenomenology. He argues that modern theory is best understood as performative and intersubjective rather than objectively true.',
  points=['Dahlhaus\'s framework: speculative, regulative and analytical traditions rest on different epistemologies. The empirical could live inside a theological world view.',
          'The Pythagorean world view survives anachronistically in the 20th century (Schillinger).',
          '"Between art and nature": Rameau and later theorists tried to ground harmony in acoustics. Sauveur claimed one could hear up to the 128th partial; Momigny admitted he heard some partials only "by analogy".',
          'A performative turn: Rameau created the discursive space theory still inhabits. Theories are validated by intersubjectivity, meaning one theorist can replicate another\'s "thought experiments", not by objective truth.',
          'GTTM (Lerdahl & Jackendoff, 1983) models the intuitions of experienced listeners as a grammar, and Krumhansl\'s experiments quantified tonal stability. Cook concludes that the epistemologies are plural.'],
  terms=[('epistemology', 'The theory of knowledge: what counts as evidence and how a claim is justified.'),
         ('intersubjectivity', 'Agreement reached by replicable procedures among observers, rather than by appeal to objective fact.')],
  theorists=[T('Fred Lerdahl & Ray Jackendoff', 'b. 1943 / b. 1945', [W('A Generative Theory of Tonal Music', '1983')], 'Formal grammar of the experienced listener.'),
             T('Carol Krumhansl', 'b. 1947', [W('Cognitive Foundations of Musical Pitch', '1990')], 'Probe-tone experiments on tonal hierarchies.'),
             T('Joseph Sauveur', '1653–1716', [], 'Founder of "acoustique"; claimed extraordinary hearing of partials.')],
  quiz=[Q('According to Cook, modern theory is best validated by…', ['divine order', 'objective physical truth', 'intersubjective replicability', 'composer intention'], 2, 'The "performative turn".')])

# ---------------- Part II speculative ----------------
chapter(id='greek', num=4, part='II', section=None, title='Greek music theory', author='Thomas J. Mathiesen', pages='109–135',
  summary='Greek writings on music and harmonics span more than eight centuries. Mathiesen describes three traditions. The Pythagorean works with number and cosmos. The Harmonicists build rational scale grids. The Aristoxenians start from what the ear perceives. He also describes the systems of tetrachords, genera, tonoi and harmoniai that later reached the West through Latin writers.',
  points=['Corpus: the <i>Division of the Canon</i> (attr. Euclid, 4th–3rd c. BCE); Aristoxenus\' <i>Harmonic Elements</i> (4th c. BCE); Cleonides; Nicomachus\' <i>Manual</i>; Theon of Smyrna; Ptolemy\'s <i>Harmonics</i>; Gaudentius; Porphyry; Aristides Quintilianus; Bacchius; Alypius (notation tables).',
          '<b>Pythagorean</b> tradition: numbers constitute reality. The tetractys (1:2:3:4) yields the consonances octave 2:1, fifth 3:2, fourth 4:3; the tone is 9:8; semitones are the limma 256:243 and the apotome 2187:2048. Archytas\'s arithmetic and harmonic means divide the octave; Plato\'s <i>Timaeus</i> builds the world-soul from them.',
          'The <b>Harmonicists</b> (known through Aristoxenus\' criticism) mapped one genus in an octave as a grid of smallest intervals.',
          '<b>Aristoxenian</b> tradition: pitch space is continuous and judged by the ear; the tone is divided into 12 parts. Three genera of tetrachord (enharmonic, chromatic, diatonic) have "shades" (Cleonides).',
          'Systems: the Greater Perfect System (two octaves from proslambanomenos to nete hyperbolaion) and the Lesser Perfect System (with the synemmenon tetrachord). Tonoi (transposition keys: 13 in Aristoxenus, 15 in later writers, 7 in Ptolemy) and the ethically charged harmoniai of Plato and Aristotle.',
          'By the late 4th century CE the traditions blurred. Martianus Capella, Boethius and Cassiodorus passed on what remained.'],
  rules=[{'text': 'Consonances are the ratios of the tetractys: 2:1 octave, 3:2 fifth, 4:3 fourth (plus 3:1 and 4:1).', 'who': 'Pythagorean tradition (Division of the Canon; Nicomachus)'},
         {'text': 'The tone is the difference between fifth and fourth (9:8) and cannot be divided into two equal rational halves.', 'who': 'Division of the Canon'},
         {'text': 'The ear, not number, judges intervals; a tetrachord spans a fourth of 2½ tones and is divided by two movable notes.', 'who': 'Aristoxenus'}],
  terms=[('tetrachord', 'Four notes spanning a fourth; outer notes fixed, inner two movable by genus.'),
         ('genus (pl. genera)', 'Enharmonic, chromatic or diatonic tuning of the tetrachord\'s inner notes.'),
         ('Greater Perfect System', 'Two-octave scale of four tetrachords plus proslambanomenos; mese is the centre.'),
         ('tonos / harmonia', 'Tonos: a transposition level of the system. Harmonia: an older scale-type with ethical character (Dorian, Phrygian…).'),
         ('limma / apotome', 'The Pythagorean minor (256:243) and major (2187:2048) semitones.')],
  theorists=[T('Pythagoras', 'c. 570–c. 495 BCE', [], 'Legendary discoverer of the consonant ratios (the blacksmith story).'),
             T('Archytas', 'fl. c. 400–350 BCE', [], 'Means and the three genera in ratios.'),
             T('Aristoxenus', 'b. c. 375–360 BCE', [W('Harmonic Elements', '4th c. BCE')], 'Ear-based theory of continuous pitch space.'),
             T('Claudius Ptolemy', 'fl. 127–48 CE', [W('Harmonics', '2nd c. CE')], 'Synthesis of reason and perception; seven tonoi.'),
             T('Nicomachus of Gerasa', 'fl. c. 100–150 CE', [W('Manual of Harmonics', '2nd c. CE')], 'Pythagorean manual; source for Boethius.'),
             T('Cleonides', '2nd c. CE', [W('Introduction to Harmonics', '2nd c. CE')], 'Aristoxenian epitome; shades of the genera.')],
  quiz=[Q('What is the Pythagorean ratio of the tone?', ['3:2', '9:8', '256:243', '81:80'], 1, 'The difference between the fifth (3:2) and the fourth (4:3).'),
        Q('Which tradition judged intervals by ear in a continuous pitch space?', ['Pythagorean', 'Aristoxenian', 'Harmonicist', 'Platonic'], 1, 'Aristoxenus divides the tone into twelve parts.'),
        Q('The central note of the Greater Perfect System is…', ['proslambanomenos', 'mese', 'nete', 'hypate'], 1, 'Mese, "the middle".')],
  tools=['tuning-lab'])

chapter(id='transmission', num=5, part='II', section=None, title='The transmission of ancient music theory into the Middle Ages', author='Calvin M. Bower', pages='136–167',
  summary='Bower follows how Greek musical thought turned into Latin "musica". Its path ran through Roman encyclopedists, Martianus Capella and Boethius to the Carolingian revival, where it met chant and produced a new kind of theory.',
  points=['Latin sources: Varro\'s liberal arts, Censorinus, Calcidius and Macrobius on Plato, Augustine\'s <i>De musica</i> (387–89, on rhythm and number).',
          'Martianus Capella\'s <i>De nuptiis</i> (early 5th c.) fixed the seven liberal arts. Its book on Harmonia borrows from Aristides Quintilianus.',
          'Boethius\' <i>De institutione musica</i> (c. 500) passed on Pythagorean ratios, the Greater Perfect System and the monochord. It also gave the triad musica mundana (of the spheres), humana (of body and soul) and instrumentalis (sounding music). Music belongs to the quadrivium as discrete quantity related to other quantity.',
          'Cassiodorus (<i>Institutiones</i>) and Isidore (<i>Etymologiae</i>) were encyclopedists of a Christian culture of learning.',
          'In the Carolingian era (Charlemagne, d. 814; Alcuin), Martianus and Boethius were glossed. Aurelian of Réôme and Regino of Prüm wrote early "theory". The <i>Musica</i> and <i>Scolica enchiriadis</i> invented a new tetrachord (T–S–T) of the four finals and the daseian notation.',
          'The problem of the 10th–11th centuries was how to fit chant into the quantitative system and account for its chromatic "faults" (vitia).'],
  terms=[('quadrivium', 'Arithmetic, music, geometry, astronomy: the four mathematical arts.'),
         ('musica mundana / humana / instrumentalis', 'Boethius\' three kinds of music: cosmic, human, and sounding.'),
         ('daseian notation', 'Enchiriadis signs built on the T–S–T tetrachord of the finals.')],
  theorists=[T('Augustine', '354–430', [W('De musica', '387–89')], 'Music as the science of measuring well (rhythm and number).'),
             T('Martianus Capella', 'fl. early 5th c.', [W('De nuptiis Philologiae et Mercurii', 'before 439')], 'Canon of seven liberal arts.'),
             T('Boethius', 'c. 480–c. 524', [W('De institutione musica', 'c. 500')], 'Main conduit of Greek theory to the Latin West.'),
             T('Cassiodorus', 'c. 485–c. 580', [W('Institutiones', '6th c.')], 'Monastic encyclopedist (Vivarium).'),
             T('Isidore of Seville', 'c. 560–636', [W('Etymologiae', '7th c.')], 'Sounds perish unless memory holds them.'),
             T('Aurelian of Réôme', 'fl. mid-9th c.', [W('Musica disciplina', 'mid-9th c.')], 'Early Carolingian treatise on the modes.'),
             T('Hucbald of Saint-Amand', 'c. 840–930', [W('Musica (De harmonica institutione)', 'c. 900')], 'Fits chant into the Greek system.')],
  quiz=[Q('Boethius\' three kinds of music are…', ['plainchant, organum, motet', 'mundana, humana, instrumentalis', 'theorica, practica, poetica', 'Dorian, Phrygian, Lydian'], 1, 'Cosmic, human and sounding music.'),
        Q('Who fixed the canon of the seven liberal arts?', ['Augustine', 'Martianus Capella', 'Isidore', 'Alcuin'], 1, 'De nuptiis Philologiae et Mercurii.')])

chapter(id='canonics', num=6, part='II', section=None, title='Medieval canonics', author='Jan Herlinger', pages='168–192',
  summary='The canon is the monochord. Medieval theorists defined pitches by dividing its string, and that was the only exact way they had to represent tuning. Herlinger surveys diatonic Pythagorean divisions, 15th-century just divisions, and the rarer chromatic and enharmonic monochords.',
  points=['A division defines pitches step by step as ratios of string lengths. Meyer catalogues 143 medieval divisions; 13 of them are chromatic or enharmonic.',
          '<i>Magadis in utraque parte</i> (by c. 1100) reproduces the Greek system in Pythagorean tuning: tones 9:8, semitones 256:243, and 2187:2048 between b♮ and b♭.',
          'Pythagorean tuning makes octaves and fifths pure. Thirds and sixths are harsh (the ditone is 81:64), so they were treated as dissonant or imperfect. The archetypal medieval cadence expands a major sixth to an octave.',
          'Just tuning adds pure thirds (5:4). Ramis de Pareia\'s <i>Musica practica</i> (1482) gave a just monochord and an eight-syllable solmization. This provoked Burzio\'s attack (1487) and Spataro\'s defence (1491).',
          'Some 15th-century "schismatic" divisions (e.g., <i>Divide primo</i>) obtain nearly pure triads from a chain of fifths.',
          'Marchetto\'s division of the whole tone into five dieses may reflect chromatic monochord theory.'],
  rules=[{'text': 'In the Pythagorean diatonic division every tone is 9:8 and every semitone within the tetrachord 256:243.', 'who': 'Magadis in utraque parte (by c. 1100); Guido'},
         {'text': 'Pure thirds require a just division: major third 5:4, minor third 6:5.', 'who': 'Ramis de Pareia, Musica practica (1482)'}],
  terms=[('canon / monochord', 'One-string instrument with a movable bridge for measuring intervals.'),
         ('Pythagorean tuning', 'Tuning built from pure fifths (3:2) and octaves only.'),
         ('just tuning', 'Tuning with pure fifths and pure thirds (5:4, 6:5).'),
         ('ditone', 'Pythagorean major third of two 9:8 tones (81:64), 22 cents sharper than 5:4.')],
  theorists=[T('Guido of Arezzo', 'c. 991–after 1033', [W('Micrologus', 'c. 1026–28')], 'Simpler monochord division; extended gamut.'),
             T('Bartolomé Ramis de Pareia', 'c. 1440–91', [W('Musica practica', '1482')], 'Just monochord; new solmization.'),
             T('Nicolò Burzio', 'c. 1450–1528', [W('Musices opusculum', '1487')], 'Defended Guidonian tradition against Ramis.'),
             T('Giovanni Spataro', 'c. 1458–1541', [W('Honesta defensio', '1491')], 'Ramis\'s pupil and defender.'),
             T('Prosdocimo de\' Beldomandi', 'c. 1380–1428', [W('Parvus tractatulus de modo monacordi dividendi', '1413')], 'Chromatic monochord; critic of Marchetto.')],
  quiz=[Q('Why were thirds treated as imperfect or dissonant in Pythagorean tuning?', ['They were too flat', 'The ditone 81:64 is wider than the pure 5:4', 'They were not in the gamut', 'Boethius forbade them'], 1, 'The ditone is about 22 cents wide.'),
        Q('Who proposed a just monochord in 1482?', ['Guido', 'Ramis de Pareia', 'Zarlino', 'Marchetto'], 1, 'Musica practica.')],
  tools=['tuning-lab'])

chapter(id='tuning', num=7, part='II', section=None, title='Tuning and temperament', author='Rudolf Rasch', pages='193–222',
  summary='Rasch traces how theorists calculated tunings. They moved from string lengths to root extraction (16th c.), logarithms (17th c.) and cents (Ellis, 19th c.). The systems run from Pythagorean and just intonation through meantone, irregular "well" temperaments and equal temperament.',
  points=['<b>Pythagorean</b>: pure fifths; 12 fifths overshoot 7 octaves by the Pythagorean comma (≈23.5 cents).',
          '<b>Just intonation</b> (Fogliano, Salinas 1577): pure fifths and thirds. It is impossible on a fixed keyboard because of the syntonic comma 81:80 (≈21.5 cents): four pure fifths make a third a comma too wide.',
          '<b>Meantone</b>: fifths narrowed by a fraction of the syntonic comma. Quarter-comma meantone makes major thirds pure; Zarlino described 2/7-comma (1558); Salinas described 1/3 and 1/4. The price is a "wolf" fifth (G♯–E♭) and unusable keys on 12-key instruments.',
          '<b>Equal temperament</b>: known in theory (Stevin c. 1600 by root extraction; Mersenne; Faulhaber with logarithms) long before it became general practice in the 19th century.',
          '<b>Irregular / well temperaments</b> (Werckmeister 1691, Neidhardt, Kirnberger, Vallotti): all keys usable, with different colours.',
          'Logarithmic measures: Sauveur\'s merides (1701); Ellis\'s cents (1/100 of an equal semitone).'],
  rules=[{'text': 'In ¼-comma meantone each fifth is narrowed by ¼ of the syntonic comma so that four fifths give a pure major third.', 'who': 'meantone practice (Aron 1523; Salinas 1577)'},
         {'text': 'In equal temperament each semitone is the twelfth root of 2 (100 cents).', 'who': 'Stevin; Mersenne'}],
  terms=[('syntonic comma', '81:80, about 21.5 cents: the difference between the Pythagorean and the just major third.'),
         ('Pythagorean comma', 'About 23.5 cents: twelve pure fifths minus seven octaves.'),
         ('wolf', 'The one badly out-of-tune fifth that collects the error of a temperament.'),
         ('cent', '1/1200 of an octave (Ellis).')],
  theorists=[T('Francisco de Salinas', '1513–90', [W('De musica libri septem', '1577')], 'Just intonation and meantone temperaments.'),
             T('Gioseffo Zarlino', '1517–90', [W('Le istitutioni harmoniche', '1558')], '2/7-comma temperament; senario.'),
             T('Simon Stevin', '1548–1620', [], 'Equal temperament by root extraction.'),
             T('Andreas Werckmeister', '1645–1706', [W('Musicalische Temperatur', '1691')], 'Circulating "well" temperaments.'),
             T('Joseph Sauveur', '1653–1716', [], 'Logarithmic interval measures (merides).'),
             T('Alexander J. Ellis', '1814–90', [W('On the Sensations of Tone (trans.)', '1875')], 'Invented the cent.')],
  quiz=[Q('What does ¼-comma meantone make pure?', ['fifths', 'major thirds', 'minor sevenths', 'all intervals'], 1, 'Four narrowed fifths give a 5:4 third.'),
        Q('The difference between a Pythagorean and a just major third is the…', ['Pythagorean comma', 'syntonic comma', 'diesis', 'schisma'], 1, '81:80.'),
        Q('Who introduced the cent?', ['Sauveur', 'Ellis', 'Helmholtz', 'Werckmeister'], 1, 'A. J. Ellis in the 19th century.')],
  tools=['tuning-lab'], links=['hip'])

chapter(id='scirev', num=8, part='II', section=None, title='The role of harmonics in the scientific revolution', author='Penelope Gouk', pages='223–245',
  summary='Between the 16th and early 18th centuries, harmonics (the mathematical science of musical ratios) was a model for natural philosophy. Gouk shows it at work in Fludd\'s neo-Platonic cosmos, in Kepler\'s planetary music and in Newton\'s colour spectrum. She then explains why music lost that status.',
  points=['Fludd\'s divine monochord shows a neo-Platonic universe held together by sympathy and tension (tonos).',
          'Kepler\'s <i>Harmonices mundi</i> (1619) found the just (syntonic diatonic) scale in the angular velocities of the planets.',
          'Newton divided the colour spectrum like the musical octave and saw the inverse-square law as foreshadowed in Pythagorean harmony. Hooke objected to his theory of colour.',
          'The body, too, was imagined as harmonic (Cheyne\'s nerves as strings).',
          'In the 18th century music lost its role as an intellectual model. Diderot\'s <i>Encyclopédie</i> follows Bacon\'s classification, not the quadrivium.'],
  terms=[('harmonics', 'The mathematical science of musical intervals; "harmonic" knowledge of nature.'),
         ('sympathy', 'Affinity between parts of the cosmos, maintained by harmonic proportion.')],
  theorists=[T('Johannes Kepler', '1571–1630', [W('Harmonices mundi', '1619')], 'Planetary harmonies in just ratios.'),
             T('Robert Fludd', '1574–1637', [W('Utriusque cosmi historia', '1617–21')], 'The divine monochord.'),
             T('Isaac Newton', '1643–1727', [W('Opticks', '1704')], 'Spectrum divided like an octave.')],
  quiz=[Q('Kepler found musical ratios in…', ['planetary orbital velocities', 'the human pulse', 'bird song', 'bell overtones'], 0, 'Harmonices mundi (1619), Book V.')])

chapter(id='acoustics', num=9, part='II', section=None, title='From acoustics to Tonpsychologie', author='Burdette Green & David Butler', pages='246–271',
  summary='The chapter runs from the discovery that pitch is frequency to Helmholtz\'s physiological acoustics and Stumpf\'s psychology of tone. It shows how the harmonic series became the foundation for theories of consonance, and how that foundation was then questioned.',
  points=['Beeckman and Galileo independently linked pitch to frequency. Mersenne gave laws of vibrating strings (length, tension, mass) and heard upper partials.',
          'Sauveur (c. 1700) described the harmonic series, nodes and the fundamental, and founded "acoustique". Rameau first used the senario (1–6), then the corps sonore (1737).',
          'Beats, and combination or difference tones (Sorge 1745; Tartini 1754 "terzo suono").',
          'Helmholtz\'s <i>Lehre von den Tonempfindungen</i> (1863; Ellis\'s English translation 1875) offered a resonance theory of hearing. Dissonance is roughness caused by beating partials; consonance is their absence.',
          'Stumpf\'s <i>Tonpsychologie</i> (1883–90) explained consonance as tonal fusion (Verschmelzung), graded octave > fifth > fourth > thirds. Psychology then took over from physics.'],
  rules=[{'text': 'Dissonance is roughness produced by beats between the partials of two tones.', 'who': 'Helmholtz (1863)'},
         {'text': 'Consonance is the degree to which two tones fuse into one impression.', 'who': 'Stumpf, Tonpsychologie (1883–90)'}],
  terms=[('harmonic series', 'Partials at whole-number multiples of a fundamental frequency.'),
         ('corps sonore', 'Rameau\'s sounding body, whose partials generate the major triad.'),
         ('tonal fusion (Verschmelzung)', 'Stumpf\'s measure of how far two tones are heard as one.'),
         ('difference tone', 'A third sound heard at the frequency difference of two loud tones (Tartini).')],
  theorists=[T('Galileo Galilei', '1564–1642', [], 'Pitch depends on frequency.'),
             T('Marin Mersenne', '1588–1648', [W('Harmonie universelle', '1636–37')], 'Laws of strings; heard partials.'),
             T('Joseph Sauveur', '1653–1716', [], 'Harmonic series; acoustics as a science.'),
             T('Giuseppe Tartini', '1692–1770', [W('Trattato di musica', '1754')], 'Terzo suono (difference tone).'),
             T('Hermann von Helmholtz', '1821–94', [W('Die Lehre von den Tonempfindungen', '1863')], 'Physiological acoustics; beats theory of dissonance.'),
             T('Carl Stumpf', '1848–1936', [W('Tonpsychologie', '1883–90')], 'Tonal fusion.')],
  quiz=[Q('Helmholtz explained dissonance as…', ['tonal fusion', 'roughness from beating partials', 'mathematical complexity of ratios', 'cultural habit'], 1, 'Die Lehre von den Tonempfindungen (1863).'),
        Q('Stumpf\'s key concept is…', ['corps sonore', 'Verschmelzung (fusion)', 'Klang', 'Ursatz'], 1, 'Tonpsychologie (1883–90).')],
  tools=['tuning-lab'])

chapter(id='math', num=10, part='II', section=None, title='Music theory and mathematics', author='Catherine Nolan', pages='272–306',
  summary='Nolan follows the bond between music theory and mathematics: Pythagorean number, geometric images of pitch and time, combinatorics, and the 20th-century algebra of sets, groups and transformations.',
  points=['Nicomachus tells the (physically impossible) story of Pythagoras discovering the consonances from the weights of blacksmiths\' hammers. It is a founding myth.',
          'Pythagoreanism holds that numbers are the elements of reality and that ratios explain cosmic order. Zarlino\'s <i>senario</i> (numbers 1–6) was challenged by Vincenzo Galilei\'s physical explanation (1589).',
          'Geometric images: Boethian monochords, de Muris\' diagrams (1320s), Descartes, Euler\'s <i>Tonnetz</i> (1739).',
          'Combinatorics: Mersenne and Kircher counted melodies; Euler\'s "degree of agreeableness" (gradus suavitatis).',
          'Sets and groups: Babbitt (combinatoriality, 1946–60s), Forte\'s <i>Structure of Atonal Music</i> (1973), Lewin\'s <i>Generalized Musical Intervals and Transformations</i> (1987).'],
  terms=[('senario', 'Zarlino\'s numbers 1–6, which generate all consonances.'),
         ('Tonnetz', 'A lattice of pitches related by fifths and thirds (Euler, Oettingen, Riemann).'),
         ('pitch-class set', 'An unordered collection of pitch classes (mod 12) studied as an abstract object.'),
         ('transformation', 'A function that maps one musical object to another (Lewin).')],
  theorists=[T('Leonhard Euler', '1707–83', [W('Tentamen novae theoriae musicae', '1739')], 'Gradus suavitatis; first Tonnetz.'),
             T('Vincenzo Galilei', 'c. 1520–91', [W('Discorso intorno all\'opere di messer Gioseffo Zarlino', '1589')], 'Physical, not numerical, account of consonance.'),
             T('Allen Forte', '1926–2014', [W('The Structure of Atonal Music', '1973')], 'Pitch-class set theory.'),
             T('David Lewin', '1933–2003', [W('Generalized Musical Intervals and Transformations', '1987')], 'GIS and transformational networks.')],
  quiz=[Q('Who wrote Generalized Musical Intervals and Transformations (1987)?', ['Forte', 'Lewin', 'Babbitt', 'Perle'], 1, 'Lewin\'s GIS.'),
        Q('Zarlino\'s senario consists of…', ['the numbers 1–6', 'six modes', 'six hexachords', 'six rhythmic modes'], 0, 'All consonances arise from ratios within 1–6.')],
  tools=['tonnetz', 'row-matrix'])

# ---------------- Part III A ----------------
chapter(id='earlymodes', num=11, part='III', section='A · Mapping tonal spaces', title='Notes, scales, and modes in the earlier Middle Ages', author='David E. Cohen', pages='307–363',
  summary='Two foundations of Western music, the discrete pitch and the scale, were built in the Carolingian era, when cantors joined the chant tradition to Greek harmonics. Cohen follows the eight modes, the note-letters, the tetrachord of the finals and Guido\'s innovations.',
  points=['The eight modes (toni) of chant probably came from the Byzantine oktoechos. They were paired as authentic/plagal on four finals: protus, deuterus, tritus and tetrardus (D, E, F, G).',
          'Tonaries list chants by mode. Aurelian\'s <i>Musica disciplina</i> describes modes in qualitative, grammatical terms.',
          'Hucbald (c. 900) gives the nine intervals of chant and alphabetic signs, and shows that the finals form a T–S–T tetrachord (D E F G). The <i>Enchiriadis</i> treatises do the same with daseian signs.',
          'The <i>Alia musica</i> applies Greek ethnic names to the modes. That is the origin of "Dorian" for mode 1, a misreading of the Greek tonoi.',
          'The <i>Dialogus de musica</i> (c. 1000) fixes letters A–G with Γ below and b♭/b♮, and defines modes by final and range (ambitus).',
          'Guido (<i>Micrologus</i> c. 1026–28; <i>Prologus</i>; <i>Epistola ad Michahelem</i>) introduced staff lines (F and C), the syllables ut re mi fa sol la from the hymn <i>Ut queant laxis</i>, and the affinities of notes a fifth apart.',
          'Hermannus Contractus defined modes by the species of fourth and fifth.'],
  rules=[{'text': 'The four finals are D, E, F, G (protus, deuterus, tritus, tetrardus); each has an authentic and a plagal mode.', 'who': 'Carolingian modal theory; Dialogus'},
         {'text': 'Authentic modes range about an octave above the final; plagal modes from a fourth below to a fifth above.', 'who': 'Dialogus de musica; Guido'},
         {'text': 'Mi–fa is always the semitone; the syllables ut re mi fa sol la name a hexachord T–T–S–T–T.', 'who': 'Guido, Epistola ad Michahelem'}],
  terms=[('tonus / modus / tropus', 'Names for the eight melodic categories of chant.'),
         ('final (finalis)', 'The note on which a chant ends; defines the mode.'),
         ('ambitus', 'The range of a melody relative to its final (authentic vs plagal).'),
         ('tonary', 'A list of chants arranged by mode.'),
         ('oktoechos', 'The Byzantine system of eight modes.')],
  theorists=[T('Hucbald of Saint-Amand', 'c. 840–930', [W('De harmonica institutione', 'c. 900')], 'Intervals, letters and the tetrachord of finals.'),
             T('Anonymous', '', [W('Musica enchiriadis / Scolica enchiriadis', 'late 9th c.')], 'Daseian notation; T–S–T tetrachords.'),
             T('Anonymous', '', [W('Alia musica', '9th–10th c.')], 'Greek ethnic names applied to the church modes.'),
             T('Anonymous', '', [W('Dialogus de musica', 'c. 1000')], 'Letter names, Γ, modes by final and ambitus.'),
             T('Guido of Arezzo', 'c. 991–after 1033', [W('Micrologus', 'c. 1026–28'), W('Epistola ad Michahelem', 'c. 1030')], 'Staff, solmization syllables, affinities.'),
             T('Hermannus Contractus', '1013–54', [W('Musica', 'before 1054')], 'Modes by species of fourth and fifth.')],
  quiz=[Q('The finals of the four maneriae are…', ['C D E F', 'D E F G', 'A B C D', 'G A B C'], 1, 'Protus D, deuterus E, tritus F, tetrardus G.'),
        Q('Where did "Dorian" as the name of mode 1 come from?', ['Plato', 'Alia musica', 'Glarean', 'Boethius'], 1, 'The Alia musica applied the Greek names to the church modes.'),
        Q('Guido\'s syllables come from the hymn…', ['Veni Creator', 'Ut queant laxis', 'Ave maris stella', 'Dies irae'], 1, 'Each line starts a step higher.')],
  tools=['modes', 'gamut'])

chapter(id='renmodes', num=12, part='III', section='A · Mapping tonal spaces', title='Renaissance modal theory', author='Cristle Collins Judd', pages='364–406',
  summary='"Mode" is one of the most layered Renaissance terms. Judd reads it from three sides: theory treatises, printed music collections and editorial practice. Zarlino serves as the lens, and the central question is how mode relates to polyphony.',
  points=['Practical manuals (the cantorinus; Vanneus\' <i>Recanetum</i>, 1533, after Gaffurio\'s <i>Practica musice</i>, 1496) kept mode tied to chant, psalm tones and mnemonics. They also attached affective characters to modes (mode 3 harsh, mode 4 adulatory, mode 6 pious…).',
          'Tinctoris (1476) and Aron\'s <i>Trattato</i> (1525) judged the mode of polyphony mainly by the tenor\'s final, range and species, with cadences as evidence.',
          'Glarean\'s <i>Dodecachordon</i> (1547) expanded the system to twelve modes, adding Aeolian (A) and Ionian (C) with their plagals, illustrated from printed polyphony.',
          'Zarlino\'s <i>Istitutioni</i> (1558) Part IV adopts twelve modes. In 1571/73 he renumbered them to begin on C.',
          'Printed collections were often ordered by mode, which shows its organizing role.',
          'Modern debate: whether modal categories actually governed polyphonic composition between 1475 and 1525.'],
  rules=[{'text': 'The mode of a polyphonic work is judged chiefly from its tenor: final, range, species and cadences.', 'who': 'Tinctoris (1476); Aron (1525)'},
         {'text': 'There are twelve modes: the eight church modes plus Aeolian and Hypoaeolian on A, Ionian and Hypoionian on C.', 'who': 'Glarean, Dodecachordon (1547)'}],
  guidelines=[{'text': 'Each mode suits certain words and affects (e.g., mode 2 tearful, mode 5 joyful).', 'who': 'Vanneus, Recanetum (1533); widely repeated'}],
  terms=[('psalm tone', 'Recitation formula for each mode; its reciting tone (tenor) helps identify the mode.'),
         ('species of fifth / fourth', 'The arrangement of tones and semitones within a fifth or fourth; together they form the octave species of a mode.'),
         ('Ionian / Aeolian', 'Glarean\'s added modes on C and A.')],
  theorists=[T('Johannes Tinctoris', 'c. 1435–1511', [W('Liber de natura et proprietate tonorum', '1476')], 'Mode in polyphony via the tenor.'),
             T('Franchino Gaffurio', '1451–1522', [W('Practica musice', '1496')], 'Comprehensive practical theory.'),
             T('Pietro Aron', 'c. 1480–after 1545', [W('Trattato della natura et cognitione di tutti gli tuoni', '1525')], 'Modal assignment of polyphony.'),
             T('Heinrich Glarean', '1488–1563', [W('Dodecachordon', '1547')], 'Twelve-mode system.'),
             T('Gioseffo Zarlino', '1517–90', [W('Le istitutioni harmoniche', '1558')], 'Twelve modes renumbered from C (1571/73).')],
  quiz=[Q('Which two modes did Glarean add?', ['Locrian and Lydian', 'Aeolian and Ionian (with plagals)', 'Mixolydian and Dorian', 'Hypermixolydian and Hypodorian'], 1, 'On A and C.'),
        Q('Aron (1525) determined the mode of a polyphonic piece mainly from…', ['the bass', 'the tenor', 'the soprano', 'the key signature'], 1, 'Tenor final, range and species.')],
  tools=['modes'])

chapter(id='seventeenth', num=13, part='III', section='A · Mapping tonal spaces', title='Tonal organization in seventeenth-century music theory', author='Gregory Barnett', pages='407–455',
  summary='The 17th century is often painted as confused, caught between modes and keys. Barnett shows a coherent practice made of solmization, transposition and key signatures, the organists\' church keys, cadence systems, and the gradual emergence of a two-mode, 24-key system.',
  points=['Tonal space rests on the gamut of letters (litterae) and hexachord syllables (voces): natural (C), hard (G) and soft (F) hexachords. <i>Cantus durus</i> has no flat; <i>cantus mollis</i> has one flat.',
          'Attempts to replace solmization (Banchieri\'s extra syllable; bocedization) failed. Musicians kept the Guidonian practice and imagined transposed pieces as untransposed (Penna, 1672).',
          'The modes were adapted to polyphony: authentic and plagal ranges were shared out among the voices, and fugue subjects and answers kept to the species of fifth and fourth.',
          'Organists\' "church keys" (tuoni ecclesiastici) based on psalm tones coexisted with the twelve modes. Cadence classifications (regular, irregular, peregrine) helped define a mode (Bononcini, 1673).',
          'English theory (Campion 1618, Simpson, Playford) identified the "key" by its bass note and its third.',
          'By about 1700 the system had settled into two modes, major and minor, transposable to all degrees (Masson 1697; Mattheson 1713 on 24 keys and their characters; Heinichen\'s circle, 1711/1728).'],
  rules=[{'text': 'A hexachord has the pattern ut re mi fa sol la (T–T–S–T–T) and stands on C (natural), G (hard, with b♮) or F (soft, with b♭).', 'who': 'Guidonian tradition'},
         {'text': 'Every key has either a major or a minor third above its final; the third decides the mode.', 'who': 'Campion (1618); Masson (1697)'}],
  terms=[('cantus durus / mollis', 'The "hard" system (no flat) or the "soft" system (one flat).'),
         ('mutation', 'Changing from one hexachord to another on a shared note.'),
         ('church keys (tuoni)', 'Organists\' eight keys derived from the psalm tones.'),
         ('cadenza regolare / irregolare / peregrina', 'Cadences on the mode\'s principal degrees, on secondary degrees, or on foreign degrees.')],
  theorists=[T('Adriano Banchieri', '1568–1634', [W('Cartella musicale', '1614')], 'Revised solmization; organists\' tones.'),
             T('Lorenzo Penna', '1613–93', [W('Li primi albori musicali', '1672')], 'Solmization and transposition for beginners.'),
             T('Giovanni Maria Bononcini', '1642–78', [W('Musico prattico', '1673')], 'Modes, cadences and counterpoint.'),
             T('Charles Masson', 'fl. 1680–1700', [W('Nouveau traité des règles pour la composition', '1697')], 'Two modes: major and minor.'),
             T('Johann Mattheson', '1681–1764', [W('Das neu-eröffnete Orchestre', '1713')], 'Twenty-four keys and their affects.')],
  quiz=[Q('Cantus mollis means a piece with…', ['no flat', 'one flat', 'two sharps', 'a minor third'], 1, 'The soft (b♭) system.'),
        Q('Who described two modes, major and minor, in 1697?', ['Masson', 'Fux', 'Penna', 'Zarlino'], 0, 'Nouveau traité.')],
  tools=['gamut', 'modes'], links=['fugue', 'partimento'])

chapter(id='dualism', num=14, part='III', section='A · Mapping tonal spaces', title='Dualist tonal space and transformation in 19th-century thought', author='Henry Klumpenhouwer', pages='456–476',
  summary='Harmonic dualism treats the minor triad as the exact mirror (inversion) of the major. Klumpenhouwer follows the idea from Hauptmann\'s dialectic through Oettingen\'s tables to Riemann\'s Klang transformations, Schritte and Wechsel, which anticipate today\'s neo-Riemannian theory.',
  points=['In 19th-century German theory two traditions coexisted: thoroughbass-based theory and harmonic dualism.',
          'Hauptmann (<i>Die Natur der Harmonik und der Metrik</i>, 1853) explained the triad dialectically: the octave is unity, the fifth duality, the third union. The minor triad is the major triad "reversed".',
          'Helmholtz denied that undertones exist physically. Oettingen (1866) nonetheless set major "tonicity" against minor "phonicity" and drew fifth/third tables.',
          'Riemann: every triad is a Klang. Major is an Oberklang generated upward from its root; minor is an Unterklang generated downward from its top note.',
          'Riemann\'s transformations: Schritte (steps, e.g., Quintschritt) and Wechsel (changes of mode, e.g., Terzwechsel, Leittonwechsel). Function labels T, S, D came in the later texts (1893).',
          'Modern neo-Riemannian theory takes over his P, L and R transformations without the dualist ontology.'],
  rules=[{'text': 'The minor triad is the inversion of the major: generated downward from its "root" (the fifth in ordinary terms).', 'who': 'Hauptmann; Oettingen; Riemann'}],
  guidelines=[{'text': 'Function labels need not map neatly onto dualist chord roots; critics who reject Riemann on this ground overstate the case.', 'who': 'Klumpenhouwer'}],
  terms=[('harmonic dualism', 'The view that major and minor are generated in opposite directions and are equal in status.'),
         ('Klang', 'Riemann\'s term for a triad as a unit with a principal tone.'),
         ('Schritt / Wechsel', 'Riemann\'s chord transformations: a move that keeps the mode / one that changes it.'),
         ('P, L, R', 'Neo-Riemannian Parallel, Leading-tone exchange, Relative.')],
  theorists=[T('Moritz Hauptmann', '1792–1868', [W('Die Natur der Harmonik und der Metrik', '1853')], 'Hegelian theory of the triad and meter.'),
             T('Arthur von Oettingen', '1836–1920', [W('Harmoniesystem in dualer Entwickelung', '1866')], 'Tonicity and phonicity; dualist tables.'),
             T('Hugo Riemann', '1849–1919', [W('Skizze einer neuen Methode der Harmonielehre', '1880'), W('Vereinfachte Harmonielehre', '1893')], 'Klang transformations; functions T S D.')],
  quiz=[Q('In Riemann\'s dualism the principal tone of a minor triad is…', ['its root', 'its third', 'its top note (fifth)', 'its bass'], 2, 'The Unterklang hangs downward from it.'),
        Q('Which neo-Riemannian operation turns C major into A minor?', ['P', 'L', 'R', 'S'], 2, 'Relative: keep C and E, move G to A.')],
  tools=['tonnetz'], links=['harmony'])

# ---------------- Part III B ----------------
chapter(id='organum', num=15, part='III', section='B · Compositional theory', title='Organum – discantus – contrapunctus in the Middle Ages', author='Sarah Fuller', pages='477–502',
  summary='Fuller follows medieval writing on music in two or more parts, in three stages. Organum (c. 850–1030) added a voice to chant by rule. Discantus (13th c.) is note-against-note polyphony in measured rhythm. Contrapunctus (14th c.) is a teachable system of consonances and progressions that leads directly to Renaissance counterpoint.',
  points=['<b>Organum</b> (<i>Musica</i> and <i>Scolica enchiriadis</i>): parallel organum at the octave or fifth, and organum at the fourth. In the latter the organal voice stops on a boundary tone to avoid a tritone and converges to the unison at the cadence (occursus).',
          'Guido\'s diaphony (<i>Micrologus</i>) prefers oblique motion and a unison occursus. Around 1100 (<i>Ad organum faciendum</i>, the Montpellier treatise) contrary motion and note-against-note writing appear.',
          '<b>Discantus</b> (Paris, 13th c.): measured polyphony (musica mensurabilis) in the Notre Dame codices. Johannes de Garlandia (c. 1250) grades concords as perfect (unison, octave), medial (fifth, fourth) and imperfect (thirds), and discords as imperfect (M6, m7), medial (tone, m6) and perfect (semitone, tritone, M7).',
          '<b>Contrapunctus</b> (14th c., "Quilibet affectans" etc.): note against note. Begin and end on perfect consonances; avoid parallel perfect consonances; prefer contrary motion; imperfect consonances lead to the nearest perfect ones (M3→5, M6→8, m3→1), with sharps if needed.',
          'The three stages show a shift from a voice added to chant to a combinatorial system of intervals that composers could learn.'],
  rules=[{'text': 'In organum at the fourth, the organal voice may not descend below the boundary tone; it holds that tone and converges to the unison at phrase ends.', 'who': 'Musica enchiriadis (late 9th c.)'},
         {'text': 'Concords: perfect = unison, octave; medial = fifth, fourth; imperfect = major and minor third.', 'who': 'Johannes de Garlandia, De mensurabili musica (c. 1250)'},
         {'text': 'Begin and end on a perfect consonance; never move in parallel perfect consonances of the same kind.', 'who': '14th-c. contrapunctus manuals'},
         {'text': 'An imperfect consonance must move to the nearest perfect consonance: major sixth to octave, major third to fifth, minor third to unison.', 'who': '14th-c. contrapunctus; Prosdocimo (1412)'}],
  terms=[('organum', 'Early polyphony: a voice added to chant by rule.'),
         ('occursus', 'The convergence of the organal voice onto the principal voice at a cadence.'),
         ('discantus', 'Measured note-against-note polyphony of the 13th century.'),
         ('contrapunctus', '"Note against note": the 14th-century system of consonant two-voice writing.'),
         ('musica ficta', 'Notes outside the gamut (added sharps and flats), e.g., to perfect a cadence.')],
  theorists=[T('Anonymous', '', [W('Musica / Scolica enchiriadis', 'late 9th c.')], 'Parallel organum and organum at the fourth.'),
             T('Guido of Arezzo', 'c. 991–after 1033', [W('Micrologus', 'c. 1026–28')], 'Diaphony with occursus.'),
             T('Johannes de Garlandia', 'fl. c. 1240–70', [W('De mensurabili musica', 'c. 1250')], 'Classification of concords and discords; rhythmic modes.'),
             T('Prosdocimo de\' Beldomandi', 'c. 1380–1428', [W('Contrapunctus', '1412')], 'Systematic contrapunctus rules.')],
  quiz=[Q('In Garlandia\'s scheme, the fifth and fourth are…', ['perfect concords', 'medial concords', 'imperfect concords', 'discords'], 1, 'Perfect = unison and octave.'),
        Q('A major sixth in 14th-century counterpoint resolves to…', ['a fifth', 'an octave', 'a unison', 'a third'], 1, 'Nearest perfect consonance.'),
        Q('What is the occursus?', ['a rhythmic mode', 'the convergence to a unison at the cadence', 'a kind of motet', 'a monochord division'], 1, 'In organum.')],
  tools=['organum'], links=['fux'])
